import type { ComponentType } from "react";
import { cn } from "@/lib/utils";

/**
 * Marcas das redes sociais e do WhatsApp, no desenho que o design entregou.
 *
 * Logo de rede não é ícone de UI. A lane de ícone funcional é o Phosphor (ver
 * CLAUDE.md); estas são marca de terceiro, e cada plataforma tem a sua.
 * Antes a página usava `InstagramLogo`/`FacebookLogo`/`LinkedinLogo` do
 * Phosphor, que são a interpretação do icon set, não a marca.
 *
 * Dois ajustes em cima dos arquivos originais:
 *
 * - `fill="currentColor"` no lugar do `#292640` cravado, pra herdarem a cor do
 *   texto, acompanharem o tema escuro e pegarem a cor de qualquer chip.
 * - O `f` do Facebook vinha como path branco por cima do bloco, enquanto o
 *   Instagram e o LinkedIn vazam o glifo. Branco cravado desaparece quando o
 *   bloco fica claro (tema escuro) e ignora o fundo. Aqui os três vazam, com
 *   `fill-rule="evenodd"`, e respondem à cor do mesmo jeito.
 *
 * Sem `width`/`height` fixos: o tamanho vem da classe, igual ao resto dos
 * ícones. Sem `<title>`: por padrão são decorativos e o nome acessível vem do
 * link que os embrulha, que já leva `aria-label`.
 *
 * O glifo ocupa a caixa de 24 inteira, sem a folga que o Phosphor deixa em
 * volta, então o padrão aqui é `h-6 w-6` e não `h-7 w-7`.
 */
type Props = {
  className?: string;
  /** Passe quando a marca carregar sentido sozinha, sem link ou texto ao lado. */
  label?: string;
};

function Marca({ d, className, label }: Props & { d: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="currentColor"
      xmlns="http://www.w3.org/2000/svg"
      className={cn("h-6 w-6 shrink-0", className)}
      {...(label ? { role: "img", "aria-label": label } : { "aria-hidden": true })}
    >
      <path fillRule="evenodd" clipRule="evenodd" d={d} />
    </svg>
  );
}

